import React, { PropsWithChildren } from 'react';
import styled from 'styled-components';

import Colors from '@dynatrace/strato-design-tokens/colors';

/** @internal */
export interface IconShapeProps {
  active?: boolean;
  color?: string;
}

const StyledIconShape = /* @__PURE__ */ styled('div')<{
  $active?: boolean;
}>(({ $active }) => ({
  border: $active ? `1px solid ${Colors.Text.Neutral.Default}` : 'none',
  display: 'flex',
  alignItems: 'center',
  justifyContent: 'center',
  borderRadius: '4px',
  width: '100%',
  height: '100%',
  boxSizing: 'border-box',
}));

/** @internal */
export const IconShape = ({
  active,
  children,
}: PropsWithChildren<IconShapeProps>) => {
  return <StyledIconShape $active={active}>{children}</StyledIconShape>;
};

IconShape['displayName'] = 'IconShape';
